class Solution {
    int dfs(int i, const vector<int>& a, int d, vector<int>& memo) {
        if (memo[i]) return memo[i];
        int best = 1, n = a.size();
        for (int dir : {-1, 1}) {
            for (int step = 1; step <= d; ++step) {
                int j = i + dir * step;
                if (j < 0 || j >= n || a[j] >= a[i]) break;
                best = max(best, 1 + dfs(j, a, d, memo));
            }
        }
        return memo[i] = best;
    }
public:
    int maxJumps(vector<int>& arr, int d) {
        vector<int> memo(arr.size(), 0);
        int ans = 0;
        for (int i = 0; i < (int)arr.size(); ++i)
            ans = max(ans, dfs(i, arr, d, memo));
        return ans;
    }
};
